/* CommerceForge Dev Docs - Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  /* Dark mode palette */
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --bg-card: rgba(22, 27, 34, 0.8);
  --border-color: #30363d;
  --border-accent: #238636;

  /* Text colors */
  --text-primary: #f0f6fc;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;

  /* Accent colors */
  --accent-green: #3fb950;
  --accent-cyan: #58a6ff;
  --accent-purple: #a371f7;

  /* Code */
  --code-bg: #161b22;
  --code-border: #30363d;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.5);
  --glow-green: 0 0 20px rgba(63, 185, 80, 0.3);
  --glow-cyan: 0 0 20px rgba(88, 166, 255, 0.3);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.25;
  color: var(--text-primary);
}

h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

p {
  color: var(--text-secondary);
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--accent-green);
}

/* Code blocks */
code, pre {
  font-family: 'JetBrains Mono', monospace;
}

code {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: 4px;
  padding: 0.2em 0.4em;
  font-size: 0.875em;
}

pre {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: 8px;
  padding: 1rem;
  overflow-x: auto;
}

pre code {
  background: none;
  border: none;
  padding: 0;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Navigation */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 17, 23, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-color);
  padding: 0.75rem 0;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-primary);
}

.nav-brand svg {
  width: 32px;
  height: 32px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  list-style: none;
}

.nav-links a {
  display: block;
  padding: 0.5rem 1rem;
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.nav-links a:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-links a.active {
  color: var(--accent-green);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.search-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.search-btn:hover {
  border-color: var(--accent-cyan);
  color: var(--text-primary);
}

.search-btn kbd {
  background: var(--bg-tertiary);
  padding: 0.15rem 0.4rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-family: inherit;
}

/* Hero Section */
.hero {
  padding: 4rem 0;
  text-align: center;
}

.hero h1 {
  margin-bottom: 1rem;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cyan) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero .subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 720px;
  margin: 0 auto 2rem;
}

.hero-ctas {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn-primary {
  background: var(--accent-green);
  color: #000;
}

.btn-primary:hover {
  background: #4ade80;
  box-shadow: var(--glow-green);
  color: #000;
}

.btn-secondary {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--accent-cyan);
  background: var(--bg-secondary);
}

.btn-accent {
  background: linear-gradient(135deg, var(--accent-cyan), var(--accent-purple));
  color: #fff;
}

.btn-accent:hover {
  box-shadow: var(--glow-cyan);
}

/* Cards Grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 1.5rem;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  backdrop-filter: blur(10px);
  transition: all 0.3s ease;
}

.card:hover {
  border-color: var(--accent-green);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.card-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-tertiary);
  border-radius: 10px;
  margin-bottom: 1rem;
  color: var(--accent-green);
}

.card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.card p {
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.card .btn {
  margin-top: auto;
}

/* Product Cards (Home) */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .product-cards {
    grid-template-columns: 1fr;
  }
}

.product-card {
  background: linear-gradient(180deg, var(--bg-secondary) 0%, var(--bg-primary) 100%);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2rem;
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
}

.product-card.apps::before {
  background: linear-gradient(90deg, var(--accent-green), #2ea043);
}

.product-card.storefronts::before {
  background: linear-gradient(90deg, var(--accent-cyan), #1f6feb);
}

.product-card.agents::before {
  background: linear-gradient(90deg, var(--accent-purple), #a371f7);
}

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.product-card p {
  font-size: 0.875rem;
  margin-bottom: 1.5rem;
  min-height: 3rem;
}

.product-card .btn {
  width: 100%;
  justify-content: center;
}

/* CLI Setup Section */
.cli-section {
  padding: 3rem 0;
}

.cli-tabs {
  display: flex;
  gap: 0.25rem;
  background: var(--bg-secondary);
  padding: 0.25rem;
  border-radius: 8px;
  width: fit-content;
  margin-bottom: 1rem;
}

.cli-tab {
  padding: 0.5rem 1rem;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.cli-tab:hover {
  color: var(--text-primary);
}

.cli-tab.active {
  background: var(--bg-tertiary);
  color: var(--accent-green);
}

.cli-accordion {
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1rem 1.5rem;
  background: var(--bg-secondary);
  border: none;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.accordion-header:hover {
  background: var(--bg-tertiary);
}

.accordion-header svg {
  transition: transform 0.3s ease;
}

.accordion-item.open .accordion-header {
  background: var(--bg-tertiary);
}

.accordion-item.open .accordion-header svg {
  transform: rotate(180deg);
}

.accordion-content {
  display: none;
  padding: 1.5rem;
  background: var(--bg-primary);
}

.accordion-item.open .accordion-content {
  display: block;
}

.accordion-content ol {
  list-style: decimal;
  padding-left: 1.5rem;
  color: var(--text-secondary);
}

.accordion-content ol li {
  margin-bottom: 0.75rem;
}

.accordion-content ol li::marker {
  color: var(--accent-green);
}

/* Code tabs */
.code-block {
  margin-top: 1rem;
}

.code-tabs {
  display: flex;
  gap: 0.25rem;
  padding: 0.25rem;
  background: var(--bg-tertiary);
  border-radius: 6px 6px 0 0;
  width: fit-content;
}

.code-tab {
  padding: 0.35rem 0.75rem;
  background: transparent;
  border: none;
  border-radius: 4px;
  color: var(--text-muted);
  font-size: 0.75rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.code-tab:hover {
  color: var(--text-secondary);
}

.code-tab.active {
  background: var(--code-bg);
  color: var(--accent-green);
}

.code-content {
  background: var(--code-bg);
  border: 1px solid var(--border-color);
  border-top: none;
  border-radius: 0 0 8px 8px;
  padding: 1rem;
  overflow-x: auto;
}

.code-content code {
  background: none;
  border: none;
  padding: 0;
  font-size: 0.875rem;
  color: var(--text-primary);
}

/* Launch CTA Section */
.launch-section {
  padding: 3rem 0;
}

.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

@media (max-width: 700px) {
  .launch-grid {
    grid-template-columns: 1fr;
  }
}

.launch-card {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-tertiary));
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2rem;
  position: relative;
}

.launch-card h3 {
  margin-bottom: 0.75rem;
}

.launch-card p {
  margin-bottom: 1.5rem;
}

/* Community Section */
.community-section {
  padding: 3rem 0;
}

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

@media (max-width: 900px) {
  .community-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 500px) {
  .community-grid {
    grid-template-columns: 1fr;
  }
}

.community-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  transition: all 0.2s ease;
}

.community-card:hover {
  border-color: var(--accent-cyan);
  background: var(--bg-secondary);
}

.community-card svg {
  width: 24px;
  height: 24px;
  color: var(--accent-cyan);
  flex-shrink: 0;
}

.community-card span {
  font-size: 0.875rem;
  font-weight: 500;
}

/* Footer */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  padding: 3rem 0 1.5rem;
  margin-top: 4rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 2rem;
}

@media (max-width: 800px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 500px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--text-primary);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.5rem;
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.footer-col a:hover {
  color: var(--accent-cyan);
}

.footer-bottom {
  padding-top: 1.5rem;
  border-top: 1px solid var(--border-color);
  text-align: center;
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* Section spacing */
.section {
  padding: 3rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.section-header h2 {
  margin-bottom: 0.75rem;
}

.section-header p {
  max-width: 600px;
  margin: 0 auto;
}

/* Docs Layout (with sidebar) */
.docs-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 2rem;
  padding: 2rem 0;
}

@media (max-width: 900px) {
  .docs-layout {
    grid-template-columns: 1fr;
  }
}

/* Sidebar */
.sidebar {
  position: sticky;
  top: 80px;
  height: fit-content;
  max-height: calc(100vh - 100px);
  overflow-y: auto;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  transition: all 0.3s ease;
}

.sidebar.collapsed {
  width: 60px;
  padding: 1rem 0.5rem;
}

.sidebar.collapsed .sidebar-title,
.sidebar.collapsed .sidebar-nav,
.sidebar.collapsed .sidebar-footer span {
  display: none;
}

.sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}

.sidebar-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sidebar-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}

.sidebar-toggle:hover {
  border-color: var(--accent-cyan);
  color: var(--text-primary);
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.sidebar-nav a {
  display: block;
  padding: 0.5rem 0.75rem;
  color: var(--text-secondary);
  font-size: 0.875rem;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.sidebar-nav a:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.sidebar-nav a.active {
  background: rgba(63, 185, 80, 0.1);
  color: var(--accent-green);
}

.sidebar-footer {
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border-color);
}

/* Docs Content */
.docs-content {
  min-width: 0;
}

.docs-hero {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border-color);
}

.docs-hero h1 {
  margin-bottom: 0.75rem;
}

.docs-hero p {
  font-size: 1.125rem;
}

/* Grid layouts */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

@media (max-width: 800px) {
  .grid-3, .grid-2 {
    grid-template-columns: 1fr;
  }
}

/* Small cards */
.small-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  padding: 1.25rem;
  transition: all 0.2s ease;
}

.small-card:hover {
  border-color: var(--accent-green);
}

.small-card h4 {
  font-size: 0.875rem;
  margin-bottom: 0.5rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.small-card p {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Feature list */
.feature-list {
  list-style: none;
}

.feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border-color);
}

.feature-list li:last-child {
  border-bottom: none;
}

.feature-list svg {
  width: 20px;
  height: 20px;
  color: var(--accent-green);
  flex-shrink: 0;
  margin-top: 0.1rem;
}

/* Protocol diagram */
.protocol-actors {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin: 2rem 0;
}

@media (max-width: 800px) {
  .protocol-actors {
    grid-template-columns: repeat(2, 1fr);
  }
}

.actor-card {
  background: linear-gradient(180deg, var(--bg-secondary), var(--bg-primary));
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  text-align: center;
}

.actor-card h4 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
  color: var(--accent-cyan);
}

.actor-card p {
  font-size: 0.8rem;
}

/* Steps */
.steps {
  counter-reset: step;
}

.step {
  display: flex;
  gap: 1rem;
  padding: 1rem 0;
}

.step::before {
  counter-increment: step;
  content: counter(step);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: var(--accent-green);
  color: #000;
  font-weight: 700;
  font-size: 0.875rem;
  border-radius: 50%;
  flex-shrink: 0;
}

.step-content h4 {
  margin-bottom: 0.25rem;
}

/* Support cards */
.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
}

.support-card h3 {
  margin-bottom: 0.75rem;
}

.support-card ul {
  list-style: none;
}

.support-card li {
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--border-color);
}

.support-card li:last-child {
  border-bottom: none;
}

.support-card a {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

.support-card a:hover {
  color: var(--accent-cyan);
}

/* Utility */
.text-green { color: var(--accent-green); }
.text-cyan { color: var(--accent-cyan); }
.text-purple { color: var(--accent-purple); }
.text-muted { color: var(--text-muted); }

.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }

.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }

/* Responsive nav */
@media (max-width: 800px) {
  .nav-links {
    display: none;
  }

  h1 { font-size: 2rem; }
  h2 { font-size: 1.5rem; }
}

